      Plot.rectY(r.push.map((p, i) => ({i, p})), {x1: d => d.i + 0.6, x2: d => d.i + 1.4, y: "p", fill: s.blue}),
      Plot.ruleY([1], {stroke: s.ink, strokeDasharray: "4,3"})
    ]
  });
  return html`<div>${top}${bottom}</div>`;
}
```

